import json, math

def r2(n):
    # return number of integer solutions (x,y) to x^2+y^2=n, counting order and signs
    # factor n
    temp = n
    prod = 1
    for p in range(2, int(math.isqrt(temp)) + 1):
        if temp % p == 0:
            exp = 0
            while temp % p == 0:
                temp //= p
                exp += 1
            if p % 4 == 3:
                if exp % 2 == 1:
                    return 0
                # even exponent does not affect the product
            elif p % 4 == 1:
                prod *= (exp + 1)
            # p == 2 does not affect the product
    # remaining prime factor
    if temp > 1:
        if temp % 4 == 3:
            return 0
        elif temp % 4 == 1:
            prod *= 2  # exponent is 1, so (1+1)
    return 4 * prod

limit = 500
vals = []
for n in range(1, limit):
    if r2(n) == 12:
        vals.append(n)
ans = sum(vals)
print(ans)
print(json.dumps(sorted(vals)))
